    "content": "11月28日，著名演员张凯丽的母亲刘玉瑞“以92岁高龄接受肾移植手术”的传言引发关注。 极目新闻记者注意到，网络流传的视频显示，张凯丽怀抱鲜花来到北京友谊医院看望做完手术的母亲，并按照母亲的要求，给为其治疗的田野专家团队献上“恩重如山”的锦旗。 视频结尾，张凯丽将出院的母亲送上了前往深圳的飞机，她感慨，家人的平安就是最大的幸福与宽慰，人生的经历就是“一个坎一个坎”，她更希望母亲能够“活到100岁”。 极目新闻记者注意到，视频中，张凯丽其实并没有提到母亲接受的是肾移植手术，只是称赞此次为母亲进行治疗的田野专家团队时提…"
