    "content": "11月28日晚，我国探月工程嫦娥六号从月球背面采回的月壤样品在上海科技馆“从地球到天宫”展览上与观众见面。 展柜中的月壤共85.5毫克，与科学家用来确定月背火山喷发年代的岩屑来自同一批样品。展期从12月1日起为期两个月，公众无需购买科技馆门票，即可在馆内地下一层公共区域近距离观看人类首次获取的月背样品。 嫦娥六号从月球背面采回的月壤样品。 上海科技馆 供图 2024年6月，嫦娥六号圆满完成人类首次月背无人采样返回任务，从月球背面的南极-艾特肯盆地，带回1935.3克月背样品，填补了人类月背探测的科研空白，是我国探月…"
