    "author": "",
    "description": "中新网北京11月28日电 (记者 吕少威 董泽宇)由北京奥运城市发展促进会、北京科技大学联合主办的“双奥文化进校园暨北京科技大学奥运名人堂”主题活动28日在北京科技大学体育馆举办。本次活动以“奥运遗产 传承永续”为主题，持续推动双奥文化浸润校园、滋养青年成长，来自北京市大中小学的500余名学生代表现场参与活动。",
    "content": "中新网北京11月28日电 (记者 吕少威 董泽宇)由北京奥运城市发展促进会、北京科技大学联合主办的“双奥文化进校园暨北京科技大学奥运名人堂”主题活动28日在北京科技大学体育馆举办。本次活动以“奥运遗产 传承永续”为主题，持续推动双奥文化浸润校园、滋养青年成长，来自北京市大中小学的500余名学生代表现场参与活动。"
