    "pub_date": "2026-11-28 21:26:26",
    "author": "",
    "description": "中新网巴西累西腓11月28日电 “2026中国—巴西文明交流互鉴论坛”日前在巴西累西腓市成功举行。中国外文局副局长于运全、巴西驻中国大使高望视频致辞。中国驻累西腓总领事石琦、巴西科技创新部部长特别代表乔治·布拉加出席论坛并致辞，中国外文局美洲传播中心主任辛峰、累西腓市政府机构关系秘书劳尔·亨利分别代表主办单位致辞。江苏省广播电视总台副台长任桐、北京师范大学艺术与传媒学院院长胡智锋、巴西法学教授埃万德罗·卡瓦略(高文勇)在论坛上作主旨发言…",
    "content": "中新网巴西累西腓11月28日电 “2026中国—巴西文明交流互鉴论坛”日前在巴西累西腓市成功举行。中国外文局副局长于运全、巴西驻中国大使高望视频致辞。中国驻累西腓总领事石琦、巴西科技创新部部长特别代表乔治·布拉加出席论坛并致辞，中国外文局美洲传播中心主任辛峰、累西腓市政府机构关系秘书劳尔·亨利分别代表主办单位致辞。江苏省广播电视总台副台长任桐、北京师范大学艺术与传媒学院院长胡智锋、巴西法学教授埃万德罗·卡瓦略(高文勇)在论坛上作主旨发言。"
