    "description": "新华社阿克拉11月28日电（记者高剑飞）弗里敦消息：由中铁七局集团有限公司、郑州铁路技师学院和弗里敦理工学院共同筹建的卓越技能学院27日在塞拉利昂首都弗里敦启动第二期培训项目。 塞拉利昂技术与高等教育部部长哈贾·拉玛图莱·武里致辞表示，学院二期项目充分体现了技术教育的重要性。武里高度评价中方为塞拉利昂民众特别是青年提供学习实用技能所作的努力。 弗里敦理工学院校长桑巴·莫里巴介绍，二期项目的课程包括汽车电器维修技术、电子商务与酒店管理，旨…",
    "content": "新华社阿克拉11月28日电（记者高剑飞）弗里敦消息：由中铁七局集团有限公司、郑州铁路技师学院和弗里敦理工学院共同筹建的卓越技能学院27日在塞拉利昂首都弗里敦启动第二期培训项目。 塞拉利昂技术与高等教育部部长哈贾·拉玛图莱·武里致辞表示，学院二期项目充分体现了技术教育的重要性。武里高度评价中方为塞拉利昂民众特别是青年提供学习实用技能所作的努力。 弗里敦理工学院校长桑巴·莫里巴介绍，二期项目的课程包括汽车电器维修技术、电子商务与酒店管理，旨在帮助缓解本地技师短缺和数字技能不足的问题。他对中铁七局、中方合作院校及塞中政府…"
