    "author": "",
    "description": "新华社深圳11月28日电（记者王丰、梁希之）记者从28日闭幕的第二十八届中国国际高新技术成果交易会上获悉，本届高交会累计吸引48万余人次专业观众到场，其中国际观众超4.5万人次；展会共迎来1365个采购团参观采购，现场促成570余项供需对接、投融资对接项目签约，意向成交金额突破1750亿元。 本届高交会以“创新引领变革，合作链接全球”为主题，汇聚全球120余个国家和地区的5000余家科创主体，在40万平方米的展馆内完成了一场科创力量的集…",
    "content": "新华社深圳11月28日电（记者王丰、梁希之）记者从28日闭幕的第二十八届中国国际高新技术成果交易会上获悉，本届高交会累计吸引48万余人次专业观众到场，其中国际观众超4.5万人次；展会共迎来1365个采购团参观采购，现场促成570余项供需对接、投融资对接项目签约，意向成交金额突破1750亿元。 本届高交会以“创新引领变革，合作链接全球”为主题，汇聚全球120余个国家和地区的5000余家科创主体，在40万平方米的展馆内完成了一场科创力量的集中会师，人气、专业度和意向成交金额等同步攀升；22个专业展区全覆盖产业链上下游，…"
