    "category": "新闻",
    "title": "“生态水”变“发展水”：北京河湖的幸福答卷",
    "link": "http://www.news.cn/20261128/134c35ce19b9414e87a3b411dcf77bc4/c.html",
    "pub_date": "2026-11-28 20:31:00",
    "author": "",
    "description": "新华社北京11月28日电（记者田晨旭）冬日的亮马河，水面映着岸边建筑。午后的亮马东院，咖啡香气混着河风，游客们错落地坐在河畔，享受惬意时光。从昔日水脉不畅、岸线荒芜，到如今水清岸绿、游人如织，亮马河的变迁，正是北京水系治理成果的一个缩影。 近年来，北京市以河长制为统筹，一条条河从“单一城市水道”蜕变为“多元生活水岸”，亮马河、坝河、昆玉河、凉水河等河流纷纷出圈。守着眼前的水脉，北京用创意和情怀打造出一个个风情各异的水岸街区。 河流治理的…",
