    "content": "（哈尔滨综合讯）位于中国哈尔滨的 侵华日军第七三一部队罪证陈列馆 公布从日本征集回流的三件化学战新罪证，揭示侵华日军自上而下、成体系地实施化学战。 新华社星期五（11月27日）报道，这三件证据分别是制式撒毒器补给罐、化学兵教学讲义及寒地工兵演习资料。 其中，“九五式”手动便携式撒毒器补给罐外观近似民用灭火器，内壁有抵御糜烂性毒剂腐蚀的防护涂层，满载可装九公斤芥子气毒剂。陈列馆研究人员介绍，撒毒器主要装填芥子气等糜烂性毒剂，常由化学兵穿戴全套防护装具后背负操作。 另外两件证据是1942年编成的39页教学讲义《瓦斯修业…"
