    "description": "标准是经济活动和社会发展的技术支撑，更是产业竞争的制高点。27日召开的国务院常务会议提出要系统优化标准体系，推动行业标准有序转化为国家标准；要强化高质量标准供给，前瞻性做好新兴产业和未来产业标准布局等要求。这释放出鲜明信号：管行业必须管标准，要持续健全国家标准体系，以高质量标准促进经济社会高质量发展。 标准决定质量，有什么样的标准就有什么样的质量，只有高标准才有高质量。中共中央、国务院2021年印发的《国家标准化发展纲要》明确：标准是“…",
    "content": "标准是经济活动和社会发展的技术支撑，更是产业竞争的制高点。27日召开的国务院常务会议提出要系统优化标准体系，推动行业标准有序转化为国家标准；要强化高质量标准供给，前瞻性做好新兴产业和未来产业标准布局等要求。这释放出鲜明信号：管行业必须管标准，要持续健全国家标准体系，以高质量标准促进经济社会高质量发展。 标准决定质量，有什么样的标准就有什么样的质量，只有高标准才有高质量。中共中央、国务院2021年印发的《国家标准化发展纲要》明确：标准是“国家基础性制度的重要方面”，标准化在推进国家治理体系和治理能力现代化中发挥着“基…"
