    "content": "11月28日，随着今年“貉口普查”结果发布，2026年上海市保护野生动物宣传月圆满收官。 澎湃新闻记者从上海市林业总站获悉，过去5年来，“貉口普查”项目共调查超300个社区与城市绿地，推测目前上海分布有3000到5000只野生貉个体。 自2022年起，上海市林业总站、复旦大学保护生物学研究组和山水自然保护中心联合发起“貉口普查”公民科学项目，项目依托市民志愿者力量，旨在持续摸清国家二级保护野生动物貉在上海城市社区的生存现状。 上海市林业总站介绍，2026年“貉口普查”调查覆盖上海11个行政区，新增徐汇、奉贤两区，共…"
