    "content": "据广州市中级人民法院官方微信公众号11月28日消息，楼顶天面（建筑术语）裂缝、房屋漏水，业主苦等一年，物业却以“业主投票”走程序为由一拖再拖。无奈之下，业主自掏腰包，这笔钱能要回来吗？ 近日，广州市中级人民法院二审审结一起物业服务合同纠纷案，明确物业公司对共有部分紧急渗漏负有先行维修义务，不得以维修资金未获业主表决通过为由拖延履行，判令物业公司赔偿业主天面防水全部维修费及合理装修损失。 消息称，业主汪某于2015年入住某小区。2023年7月，汪某发现楼顶有多条裂缝；2023年10月，汪某发现楼顶天面及排水沟渠裂缝增…"
