    "content": "新华社北京11月28日电（记者高亢）记者从国家数据局获悉，28日亚太数智赋能创新发展合作平台在四川成都揭牌并启动建设。 据国家数据局相关负责人介绍，平台将在数据基础设施建设、数据资源开发利用、产业数智化转型、数字文创、数字人才培养等方面，促进经验交流、资源对接、场景合作和能力建设，探索形成务实合作成果，助力弥合亚太地区数字鸿沟，促进亚太经济体共同繁荣发展。 据了解，这一平台由国家数据局、四川省人民政府推动建设，将围绕数据赋能经济社会发展，面向亚太经济体提供开放型数智赋能创新发展服务，为各经济体在APEC框架下深化区…"
