    "content": "新华社广州11月28日电（记者王优玲）住房城乡建设部有关负责人28日表示，当前，我国城市更新正从多点探索转向全面推进，要探索城市更新的新路径、新模式，转变以往重规划、轻实施的惯性思维，贯穿规划建设、运营治理全生命周期，高水平开展城市更新规划设计，实现城市高质量发展。 由中国城市规划学会主办的2026中国城市规划年会全体大会28日在广州举行。 住房城乡建设部副部长董建国在会上表示，探索全生命周期城市更新规划设计新路径，要坚持问需于民、问计于民、问效于民，将盘活改造的公共空间、服务设施、生态资源等优先用于满足民生需求。…"
