    "content": "新华社成都11月28日电（记者王曦、李杰）11月28日，随着四川绵遂资内铁路黄泥沟特大桥9号墩T构转体梁顺时针精准旋转到位，历时45分钟，总重9500吨的梁体顺利跨越既有达成铁路，标志着绵遂资内铁路全线首座跨铁路转体桥梁成功转体。 这是11月27日在四川省遂宁市安居区境内拍摄准备进行转体施工的绵遂资内铁路黄泥沟特大桥9号墩T构转体梁。新华社发 黄泥沟特大桥位于遂宁市安居区横山镇境内，由蜀道铁路投资集团主导投资、中国铁建大桥局承建，桥梁全长约1643.7米，是绵遂资内铁路的控制性工程，也是全线唯一一座需要两次转体的桥…"
