    "content": "黄金价格又涨了。 当地时间11月28日，国际贵金属价格大涨，现货黄金重新站上3650美元。 截至当日收盘，现货黄金涨2.45%，报3653.50美元/盎司；现货白银涨5.24%，报43.717美元/盎司。COMEX黄金期货涨2.44%，报3681.1美元/盎司；COMEX白银期货涨5.35%，报43.985美元/盎司。 在经历周三跌破3500美元、创下逾一年新低的剧烈调整后，金价迎来强势反弹，三周以来首次实现周度上涨。展望后市，多家华尔街投行对黄金中长期走势仍普遍看多。 金价大涨重返3650美元 自11月12日起的…"
