    "title": "日媒：日拟将研究引入核潜艇写进“安保三文件”",
    "link": "http://www.news.cn/20261128/df63399f328f4e68aedada3c68ef0f79/c.html",
    "pub_date": "2026-11-28 18:11:04",
    "author": "",
    "description": "新华社东京11月28日电（记者李子越 陈泽安）日本时事社28日报道，围绕是否引入核动力潜艇一事，日本政府考虑在年内修订的“安保三文件”中写明“启动研究并得出结论”。 报道称，日本政府将根据专家会议汇总的建议和执政党内部讨论结果，确定“安保三文件”中关于启动引入核潜艇研究的表述。 据报道，相比日本现有的柴油动力潜艇，核动力潜艇续航时间长、航速快，可搭载远程导弹垂直发射装置等，可用于强化所谓“反击能力”。 近期，日本防卫大臣小泉进次郎多次表…",
    "content": "新华社东京11月28日电（记者李子越 陈泽安）日本时事社28日报道，围绕是否引入核动力潜艇一事，日本政府考虑在年内修订的“安保三文件”中写明“启动研究并得出结论”。 报道称，日本政府将根据专家会议汇总的建议和执政党内部讨论结果，确定“安保三文件”中关于启动引入核潜艇研究的表述。 据报道，相比日本现有的柴油动力潜艇，核动力潜艇续航时间长、航速快，可搭载远程导弹垂直发射装置等，可用于强化所谓“反击能力”。 近期，日本防卫大臣小泉进次郎多次表示，在讨论引入核动力潜艇问题时“不排除任何选项”。今年10月，日本首相高市早苗在…"
