    "content": "台湾九合一地方选举开票逾两小时，国民党在台北、新北、桃园和基隆等北部县市暂居领先，但在台中、彰化和宜兰三个原执政的中部县市陷入苦战，国民党中央党部气氛凝重。 综合台湾《联合报》和TVBS新闻网报道，截至星期六（11月28日）下午6时许，民进党籍台中市长候选人何欣纯以34万7205票，领先国民党籍对手江启臣的32万5981票，两人票数差距从下午4时30分的4000多票扩大至逾2万票。 东森新闻的开票统计也显示，何欣纯领先江启臣约1万8000票。 除了台中，国民党在彰化和宜兰的选情也面临考验。民进党籍彰化县长候选人陈素…"
