    "description": "新华社沈阳11月28日电（记者武江民、赵洪南）初冬的辽宁辽阳，白塔公园里古木疏落，一座通体灰白的古塔格外醒目。这座建于辽代的辽阳白塔通高70.4米，是辽宁省内现存最高的古代砖塔。塔身砖雕精美，佛像、莲花等图案虽历经风雨，轮廓依然可辨。 11月27日拍摄的辽阳白塔。新华社记者 潘昱龙 摄 11月27日，由辽宁省历史学会、辽宁师范大学、辽阳市人民政府等单位共同举办的“辽代塔建价值阐释与活化利用”专题研讨会在辽阳举行。多位专家学者齐聚辽阳白塔…",
    "content": "新华社沈阳11月28日电（记者武江民、赵洪南）初冬的辽宁辽阳，白塔公园里古木疏落，一座通体灰白的古塔格外醒目。这座建于辽代的辽阳白塔通高70.4米，是辽宁省内现存最高的古代砖塔。塔身砖雕精美，佛像、莲花等图案虽历经风雨，轮廓依然可辨。 11月27日拍摄的辽阳白塔。新华社记者 潘昱龙 摄 11月27日，由辽宁省历史学会、辽宁师范大学、辽阳市人民政府等单位共同举办的“辽代塔建价值阐释与活化利用”专题研讨会在辽阳举行。多位专家学者齐聚辽阳白塔之下，围绕辽塔的价值挖掘、遗产保护、传播利用展开研讨，为千年古塔的当代活化探寻新…"
