    "content": "台湾“九合一”地方选举星期六（11月28日）举行投票，绿营支持者在社媒热传一段“返台投票飞机潮”视频，不少人称大受感动，但很快被证实其实是中国大陆广州白云机场的飞机降落画面。 社媒Threads账号“chi8yua”星期五（11月27日）发布一段飞机深夜密集降落视频，并写道“（深夜）12点班机”，截至星期六下午已获得逾10万人按赞，在绿营支持者中热传。 尽管这名博主并未说明视频拍摄机场是否在台湾，但他点赞了多则留言，包括“投票大军回来了”，以及民进党籍台北市长参选人沈伯洋团队常说的“戒慎恐惧”等，让不少人以为这是台…"
