    "content": "新华社布鲁塞尔11月27日电（记者朱昊晨 张兆卿 张馨文）欧盟26日在比利时布鲁塞尔举行特别峰会。由于与会领导人在欧盟长期预算和援助乌克兰问题上分歧严重，原定两天的峰会于27日凌晨提前结束。分析人士认为，此次峰会暴露出欧盟内部的结构性矛盾。随着欧洲多国重要选举临近，选举结果或将给各方达成共识增添新变数，欧盟未来恐将面临更多困难。 预算谈不拢 去年7月，欧盟委员会提出总额近2万亿欧元的2028年至2034年预算方案，不过成员国对该预算规模存在分歧。今年10月，欧盟轮值主席国爱尔兰提出削减后的折中方案，总额约1.83万…"
