    "content": "&nbsp; 律动造物创始人谢童 文｜赵芮 编辑｜张雨忻 近年来，AI正在从帮科学家查找资料、处理数据，走向直接参与科研，甚至尝试自主设计和执行实验。这一方向也被称为AI for Science（AI4S）。 材料科学是AI4S发展较快的方向之一。过去，科学家要从大量材料组合中反复试验，寻找符合要求的新材料；如今，AI已经能够帮助预测材料性能、筛选配方、设计实验，缩短早期研发过程。 但目前，材料学AI4S正在面临的一道难题是：如何从实验室走向工业生产。 实验室里的材料进入工厂后，生产规模可能从几克变成几吨。原本的温…"
