    "content": "文｜赵芮 编辑｜张雨忻 9月，抖音游戏平台上一款关于“大女主逆袭”的互动影游《遥知春雪》，在两周内吸引了120多万名玩家体验。 游戏出自一名刚毕业的女生。她没有游戏开发背景，平时喜欢写小说。借助未来序列的AI互动内容创作工具NEX，她把自己写的小说变成了一部可以玩的互动影游。在游戏中，玩家能在故事的关键节点做出选择，不同选择背后是人物不同的命运走向。 《遥知春雪》游戏试玩版 过去，做这样一款互动影游需要游戏策划、美术、开发等十多个专业岗位协作，开发周期往往以年计算。每增加一条剧情分支，也意味着数十万制作成本。 生成…"
