    "pub_date": "2026-11-28 17:03:17",
    "author": "",
    "description": "中新社北京11月28日电 (记者 孙自法)记者28日从中国航空发动机集团(中国航发)获悉，作为中国第一型自主创新研制的1000千瓦级先进民用涡轴发动机，AES100发动机双发配装镧影R6000倾转旋翼机，近日在四川什邡圆满完成采用国产可持续航空燃料(SAF)的首次飞行试验。",
    "content": "中新社北京11月28日电 (记者 孙自法)记者28日从中国航空发动机集团(中国航发)获悉，作为中国第一型自主创新研制的1000千瓦级先进民用涡轴发动机，AES100发动机双发配装镧影R6000倾转旋翼机，近日在四川什邡圆满完成采用国产可持续航空燃料(SAF)的首次飞行试验。"
