    "description": "新华社酒泉11月28日电（记者李国利、米思源）神舟二十三号和神舟二十四号航天员28日下午进行交接仪式，移交了中国空间站的钥匙。 根据任务计划安排，巴基斯坦航天员穆罕默德·齐尚·阿里将乘坐神舟二十三号飞船返回，航天员朱杨柱将留轨完成一年期在轨驻留试验，与指令长汤洪波、航天员武毅共同执行神舟二十四号载人飞行任务。 据中国载人航天工程办公室介绍，截至目前，航天员张志远、黎家盈、齐尚·阿里已完成全部既定任务，航天员张志远将担任神舟二十三号返回任…",
    "content": "新华社酒泉11月28日电（记者李国利、米思源）神舟二十三号和神舟二十四号航天员28日下午进行交接仪式，移交了中国空间站的钥匙。 根据任务计划安排，巴基斯坦航天员穆罕默德·齐尚·阿里将乘坐神舟二十三号飞船返回，航天员朱杨柱将留轨完成一年期在轨驻留试验，与指令长汤洪波、航天员武毅共同执行神舟二十四号载人飞行任务。 据中国载人航天工程办公室介绍，截至目前，航天员张志远、黎家盈、齐尚·阿里已完成全部既定任务，航天员张志远将担任神舟二十三号返回任务指令长。3名航天员将于近日搭乘飞船返回东风着陆场，还将带回来自“天宫”的“神秘…"
