    "description": "新华社北京11月28日电 美国消费者27日迎来“黑色星期五”购物日。一天前，强风暴席卷美国东海岸和西海岸等地区，引发洪水、断电等状况并扰乱交通；另据业界预测，受油价居高不下影响，今年“黑五”不少商品价格将高于往年同期。 天公不作美 风暴带来的强降雨覆盖美国东海岸和中西部多地。从纽约州到弗吉尼亚州，都报告了恶劣天气引发的水上救援。新泽西州和纽约州部分地区进入紧急状态。 这是11月26日在美国纽约拍摄的“远离防波堤”的告示。新华社记者张凤国…",
    "content": "新华社北京11月28日电 美国消费者27日迎来“黑色星期五”购物日。一天前，强风暴席卷美国东海岸和西海岸等地区，引发洪水、断电等状况并扰乱交通；另据业界预测，受油价居高不下影响，今年“黑五”不少商品价格将高于往年同期。 天公不作美 风暴带来的强降雨覆盖美国东海岸和中西部多地。从纽约州到弗吉尼亚州，都报告了恶劣天气引发的水上救援。新泽西州和纽约州部分地区进入紧急状态。 这是11月26日在美国纽约拍摄的“远离防波堤”的告示。新华社记者张凤国摄 田纳西河流域26日迎来降雪。密苏里州东部地区降雪量达到15英寸（约38厘米）…"
