    "content": "在霍尔木兹海峡游泳时，刘易斯·皮尤向右侧换气，看见一艘遇袭的油轮冒着浓烟；向左侧换气，眼前是阿曼的群山和峡湾，鱼鹰从峭壁上俯冲而下，海豚在水中嬉戏。 “每次（游泳时）向右换气，都像在看一部战争片。”皮尤对新华社记者说，“转向左边，就如同在看一部自然纪录片”。 11月中旬，这名56岁的英国耐力游泳运动员在阿曼穆桑代姆半岛附近的霍尔木兹海峡水域，分三天游了约15公里。他想亲眼看看战火让这片海变成了什么样子，再把所见所闻告诉更多人。 11月17日，一艘油轮在霍尔木兹海峡水域遇袭起火冒出浓烟。新华社发（刘易斯·皮尤基金会供…"
