    "title": "社区医院开“健身房” 医生把运动和饮食都管起来了",
    "link": "http://www.news.cn/20261128/5e90d94574034c9b8ed73e5442d20fc2/c.html",
    "pub_date": "2026-11-28 16:12:16",
    "author": "",
    "description": "新华社北京11月28日电（记者杨淑君、余佩璇）社区卫生服务中心里，开起了“健身房”。今年8月，北京市朝阳区东风社区卫生服务中心挂牌成为北京首家基层场景化医体融合运动促进健康中心。3个多月来，不少居民来这里请医生开“健康处方”，再就地锻炼。“管住嘴、迈开腿”究竟该怎么吃、怎么动？在“家门口”，他们找到了专业答案。 走进健康中心，这里环境干净敞亮，前来锻炼和康复的居民秩序井然。“平时吃得多、动得少，体检报告亮起了红灯。”33岁的北京市民刘霞…",
    "content": "新华社北京11月28日电（记者杨淑君、余佩璇）社区卫生服务中心里，开起了“健身房”。今年8月，北京市朝阳区东风社区卫生服务中心挂牌成为北京首家基层场景化医体融合运动促进健康中心。3个多月来，不少居民来这里请医生开“健康处方”，再就地锻炼。“管住嘴、迈开腿”究竟该怎么吃、怎么动？在“家门口”，他们找到了专业答案。 走进健康中心，这里环境干净敞亮，前来锻炼和康复的居民秩序井然。“平时吃得多、动得少，体检报告亮起了红灯。”33岁的北京市民刘霞第一次来，“听说这里能检测，还能健身。毕竟医院还是更专业，离家也近，很方便。” …"
