    "description": "新华社巴西戈亚尼亚11月28日电 专访｜期待巴中科研合作结出更多硕果——访巴西科学院院长纳德尔 新华社记者陆君钰 吴念 “我希望巴西和中国的年青一代承担起延续两国科研合作的重任。”巴西科学院院长、中国科学院外籍院士海伦娜·纳德尔日前接受新华社记者专访时表示，巴中两国科研优势互补、合作前景广阔，期待青年科研人员加强交流，推动两国科研合作结出更多硕果。 “巴中两国长期保持密切的经贸关系，双方高度认可彼此的科研实力，在联合研究方面有广阔的拓展…",
    "content": "新华社巴西戈亚尼亚11月28日电 专访｜期待巴中科研合作结出更多硕果——访巴西科学院院长纳德尔 新华社记者陆君钰 吴念 “我希望巴西和中国的年青一代承担起延续两国科研合作的重任。”巴西科学院院长、中国科学院外籍院士海伦娜·纳德尔日前接受新华社记者专访时表示，巴中两国科研优势互补、合作前景广阔，期待青年科研人员加强交流，推动两国科研合作结出更多硕果。 “巴中两国长期保持密切的经贸关系，双方高度认可彼此的科研实力，在联合研究方面有广阔的拓展空间。”纳德尔在首届中国—巴西青年科研人员交流会期间受访时说。 纳德尔曾多次访华…"
