    "content": "近日，在北京市丰台区杜家坎环岛北侧公交场站，一辆辆崭新的纯电动公交车依次安装机动车号牌。这批10米纯电动公交车将替换北京公交102路目前使用的无轨电车，预计年底前驶上街头。 图为即将投用的新能源公交车（受访者供图） 2026年，北京公交集团计划采购公交车2470辆，新购车辆实现100%新能源化。从车型构成看，8米、10米级车辆合计1784辆，占比达到72%。中小型车辆能够更好适配不同线路客流特点和城市道路通行条件，满足接驳地铁、复杂路况等灵活运营场景需求，进一步优化首都公交运力结构。 除动力系统更新外，车厢服务细节…"
