    "content": "新华社长春11月28日电 吉林新雪季：“雪赛”“雪街”“雪假”提质升级 新华社记者王帆、周万鹏、颜麟蕴 吉林省2026-2027新雪季开板大会暨第32届吉林雾凇冰雪节28日在中旅松花湖度假区启幕，第十届吉林冰雪产业国际博览会以“吉林雪街”模式同期开展。“雪赛”资源共享、“雪街”功能升级、“雪假”走实提质……新雪季的吉林，正在冰雪热潮中探索高质量发展新路径。 “赛不封场”共享赛事资源 漫山粉雪之上，滑雪者踏板疾驰，在雪面划出道道弧线。清晨的中旅松花湖度假区，缆车穿行林间，魔毯循环送客，雪道之上生机涌动……作为长春20…"
