    "description": "新华社成都11月28日电（记者余里）28日5时，来自中国大熊猫保护研究中心的雌性大熊猫“冉冉”，在中方1名兽医和比方1名饲养员的陪伴下，从成都天府国际机场乘机前往比利时天堂公园，续写中比大熊猫保护交流合作新篇。 大熊猫“冉冉”，2017年5月31日出生，它面庞圆润，体态匀称，性格温和，历经野化环境历练，具有较强的环境适应能力。“冉冉”此次前往比利时，将代替已回国的雌性大熊猫“好好”，延续中比大熊猫保护情缘。 2014年2月，大熊猫“星徽…",
    "content": "新华社成都11月28日电（记者余里）28日5时，来自中国大熊猫保护研究中心的雌性大熊猫“冉冉”，在中方1名兽医和比方1名饲养员的陪伴下，从成都天府国际机场乘机前往比利时天堂公园，续写中比大熊猫保护交流合作新篇。 大熊猫“冉冉”，2017年5月31日出生，它面庞圆润，体态匀称，性格温和，历经野化环境历练，具有较强的环境适应能力。“冉冉”此次前往比利时，将代替已回国的雌性大熊猫“好好”，延续中比大熊猫保护情缘。 2014年2月，大熊猫“星徽”“好好”抵达比利时天堂公园，开展为期15年的中比大熊猫保护合作。11年间，双方…"
