    "pub_date": "2026-11-28 15:24:56",
    "author": "",
    "description": "广西首个国家级海洋牧场示范区——防城港白龙珍珠湾海洋牧场金鲳鱼进入冬季捕捞季。11月26日当天捕捞越冬金鲳鱼15万斤，这些鱼经冷链园区急冻加工后，直接发往海外。今年以来，防城港金色海洋产业发展有限公司已出口深海养殖金鲳鱼500万斤，其中欧美市场约占60%，预计2027年出口量将超600万斤。 作者：陈罗 周才圣 陆懿 覃广华 新华社音视频部制作",
    "content": "广西首个国家级海洋牧场示范区——防城港白龙珍珠湾海洋牧场金鲳鱼进入冬季捕捞季。11月26日当天捕捞越冬金鲳鱼15万斤，这些鱼经冷链园区急冻加工后，直接发往海外。今年以来，防城港金色海洋产业发展有限公司已出口深海养殖金鲳鱼500万斤，其中欧美市场约占60%，预计2027年出口量将超600万斤。 作者：陈罗&nbsp;周才圣 陆懿&nbsp;覃广华 新华社音视频部制作"
