    "content": "新华社北京11月28日电 题：超强厄尔尼诺影响正加强 各地各部门部署应对 新华社记者黄垚 据气象部门消息，已发展为有监测记录以来最强的厄尔尼诺事件，将对我国今冬明春气候产生明显影响。 事实上，当前厄尔尼诺已给我国气候带来一定影响。本月上旬，随着第32号台风“查帕卡”在西北太平洋洋面生成，今年台风生成数量创下21世纪以来最高纪录。 专家分析，受超强厄尔尼诺事件发展影响，今年夏季以来西太平洋副热带高压位置持续偏北，有利于台风生成。7月至10月共生成台风23个，台风生成数量和登陆数量较常年同期明显偏多，强度整体偏强。 国…"
